  --halo-control-border: #383c46;
  --halo-control-depth: #111317;
  --halo-control-highlight: rgba(255, 255, 255, 0.14);
  --halo-control-text: #f3f4f6;

  /* Primary Action (High-Contrast White in Dark Mode) */
  --halo-primary-top: #ffffff;
  --halo-primary-bottom: #f1f2f4;
  --halo-primary-border: #e2e4e9;
  --halo-primary-depth: #c4c8d0;
  --halo-primary-highlight: rgba(255, 255, 255, 1);
  --halo-primary-foreground: #0f1013;
  --halo-primary-hover-top: #ffffff;
  --halo-primary-hover-bottom: #e5e7eb;

  /* Secondary Action */
  --halo-secondary-top: #262930;
  --halo-secondary-bottom: #1c1e24;
  --halo-secondary-border: #383c46;
  --halo-secondary-depth: #111317;
  --halo-secondary-highlight: rgba(255, 255, 255, 0.14);
  --halo-secondary-foreground: #f3f4f6;

  /* Destructive Action */
  --halo-destructive-top: #dc2626;
  --halo-destructive-bottom: #b91c1c;
  --halo-destructive-border: #991b1b;
  --halo-destructive-depth: #450a0a;
  --halo-destructive-highlight: rgba(255, 255, 255, 0.22);
  --halo-destructive-foreground: #ffffff;

  /* Inset Inputs & Wells */
  --halo-input-background: #0e0f13;
  --halo-input-border: #30343f;
  --halo-input-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.4);

  /* Elevated Overlays & Pop Cards (Apple iOS / macOS frosted liquid glass with high legibility - not too transparent) */
  --halo-elevated-background: rgba(22, 24, 30, 0.92);
  --halo-elevated-border: rgba(255, 255, 255, 0.15);
  --halo-elevated-shadow: inset 0 1px 1px 0 rgba(255, 255, 255, 0.22), inset 0 -1px 1px 0 rgba(0, 0, 0, 0.70), 0 20px 48px -6px rgba(0, 0, 0, 0.65), 0 6px 16px rgba(0, 0, 0, 0.50);
  --halo-glass-pop-background: rgba(22, 24, 30, 0.92);
  --halo-glass-pop-border: rgba(255, 255, 255, 0.15);
  --halo-glass-pop-blur: 20px;
  --halo-glass-pop-shadow: inset 0 1px 1px 0 rgba(255, 255, 255, 0.22), inset 0 -1px 1px 0 rgba(0, 0, 0, 0.70), 0 20px 48px -6px rgba(0, 0, 0, 0.65), 0 6px 16px rgba(0, 0, 0, 0.50);

  /* Focus Ring Tokens */
  --halo-focus-color: #38bdf8;
  --halo-focus-offset: 2px;
  --halo-focus-width: 2px;
  --halo-focus-offset-color: #0c0d0f;
  --halo-focus-outer-color: rgba(56, 189, 248, 0.35);
  --halo-focus-shadow: 0 0 0 var(--halo-focus-offset) var(--halo-focus-offset-color),
                       0 0 0 calc(var(--halo-focus-offset) + var(--halo-focus-width)) var(--halo-focus-color),
                       0 0 0 calc(var(--halo-focus-offset) + var(--halo-focus-width) + 1.5px) var(--halo-focus-outer-color);

  /* Typography & Canvas */
  --halo-canvas: #0c0d0f;
  --halo-canvas-card: #141518;
  --halo-canvas-subtle: #1c1e22;
  --halo-text-primary: #f6f7f9;
  --halo-text-secondary: #9ea3ae;
  --halo-text-tertiary: #656a76;

  /* Backward Compatibility Bridges */
  --halo-edge: rgba(255, 255, 255, 0.12);
  --halo-edge-soft: rgba(255, 255, 255, 0.05);
  --halo-edge-bright: rgba(255, 255, 255, 0.22);
  --halo-edge-inner: inset 0 1px 0 rgba(255, 255, 255, 0.14);
  --halo-edge-outer: 0 0 0 1px rgba(255, 255, 255, 0.08);
  --halo-highlight: linear-gradient(180deg, rgba(255, 255, 255, 0.12) 0%, rgba(255, 255, 255, 0) 100%);
  --halo-highlight-strength: 0.55;
  --halo-shadow-contact: 0 1px 2px rgba(0, 0, 0, 0.4);
  --halo-shadow-elevated: 0 1px 2px rgba(0, 0, 0, 0.4), 0 8px 24px rgba(0, 0, 0, 0.55);
  --halo-shadow-ambient: 0 16px 36px rgba(0, 0, 0, 0.6);
  --halo-shadow-compressed: inset 0 1px 2px rgba(0, 0, 0, 0.5);
  --halo-blur-sm: 0px;
  --halo-blur-md: 0px;
  --halo-blur-lg: 0px;
  --halo-blur-xl: 0px;
  --halo-refraction-strength: 0;
  --halo-refraction-offset: 0;
  --halo-noise-opacity: 0;
  --halo-glow: transparent;
}

