  --halo-destructive-foreground: #ffffff;

  --halo-input-background: #ffffff;
  --halo-input-border: #d1d5db;
  --halo-input-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.08);

  --halo-elevated-background: rgba(255, 255, 255, 0.92);
  --halo-elevated-border: rgba(255, 255, 255, 0.85);
  --halo-elevated-shadow: inset 0 1px 1px 0 rgba(255, 255, 255, 0.95), inset 0 -1px 1px 0 rgba(0, 0, 0, 0.04), 0 16px 40px -4px rgba(0, 0, 0, 0.10), 0 4px 12px rgba(0, 0, 0, 0.04);
  --halo-glass-pop-background: rgba(255, 255, 255, 0.92);
